ndif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-25T08:06:11.751Z', '2026-10-25T08:06:13.770Z', 'Order shipped', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
